+  memset(range, 0, sizeof(*range));
+  range->num_frequency = 14;
+  for (i = 0; i < range->num_frequency; i++)
+    {
+      range->freq[i].m = i + 1;
+    }
+  request->u.data.length = sizeof(*range);
+  return OK;
+}
